boostButton.addEventListener('pointercancel',()=>boosting=false);boostButton.addEventListener('lostpointercapture',()=>boosting=false);
let boostFuel=1;
function makeRock(){const r=rand(17,35),sides=Math.floor(rand(7,11)),pts=[];for(let i=0;i<sides;i++){const a=i/sides*Math.PI*2;pts.push([Math.cos(a)*r*rand(.78,1.12),Math.sin(a)*r*rand(.78,1.12)])}rocks.push({x:rand(24,w-24),y:-r-10,r,pts,rot:rand(0,6),spin:rand(-1.3,1.3),hp:1,shade:Math.random()})}
function makePickup(){pickups.push({x:rand(26,w-26),y:-20,r:10,phase:Math.random()*6.2})}
function update(dt){time+=dt;const activeBoost=boosting&&boostFuel>0;if(activeBoost)boostFuel=Math.max(0,boostFuel-dt*.42);else boostFuel=Math.min(1,boostFuel+dt*.19);document.getElementById('boostMeter').style.transform=`scaleX(${boostFuel})`;
const steer=(keys.has('arrowleft')||keys.has('a')||keys.has('touchleft')?-1:0)+(keys.has('arrowright')||keys.has('d')||keys.has('touchright')?1:0);const mult=activeBoost?1.55:1;ship.vx+=(steer*520*mult-ship.vx)*Math.min(1,dt*5.5);ship.x=clamp(ship.x+ship.vx*dt,22,w-22);ship.invuln=Math.max(0,ship.invuln-dt);
const worldSpeed=(speed+Math.min(180,time*2.15))*(activeBoost?1.32:1);distance+=worldSpeed*dt/11;ui.distance.textContent=String(Math.floor(distance)).padStart(4,'0');
for(const star of stars){star.y+=worldSpeed*dt*star.z*.45;if(star.y>h){star.y=-4;star.x=Math.random()*w}}
spawn-=dt;if(spawn<=0){makeRock();spawn=Math.max(.36,rand(.65,1.15)-time*.004)}collectSpawn-=dt;if(collectSpawn<=0){makePickup();collectSpawn=rand(2.2,3.8)}
for(let i=rocks.length-1;i>=0;i--){const o=rocks[i];o.y+=worldSpeed*dt;o.rot+=o.spin*dt;if(o.y>h+o.r){rocks.splice(i,1);continue}if(ship.invuln<=0&&Math.hypot(ship.x-o.x,ship.y-o.y)<ship.r+o.r*.72){rocks.splice(i,1);lives--;ui.lives.textContent='♥'.repeat(lives)+'<span style="color:#49606a">'+'♥'.repeat(3-lives)+'</span>';ship.invuln=1.65;shake=12;burst(o.x,o.y,'#ff9877',22);sound(145,.22,'square',.045);if(lives<=0){endRun();return}}}
for(let i=pickups.length-1;i>=0;i--){const p=pickups[i];p.y+=worldSpeed*dt;p.phase+=dt*3;if(p.y>h+30){pickups.splice(i,1);continue}if(Math.hypot(ship.x-p.x,ship.y-p.y)<ship.r+p.r+2){pickups.splice(i,1);shards++;ui.shards.textContent=String(shards).padStart(3,'0');burst(p.x,p.y,'#73f5df',13);sound(760,.13,'sine',.04);if(shards%10===0&&lives<3){lives++;ui.lives.textContent='♥'.repeat(lives)+'<span style="color:#49606a">'+'♥'.repeat(3-lives)+'</span>';sound(940,.2,'triangle',.05)}}}
for(let i=sparks.length-1;i>=0;i--){const p=sparks[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)sparks.splice(i,1)}shake=Math.max(0,shake-dt*28)
}
function shipDraw(){ctx.save();ctx.translate(ship.x,ship.y);const active=boosting&&boostFuel>0;ctx.rotate(ship.vx*.00045);if(ship.invuln>0&&Math.floor(time*15)%2===0)ctx.globalAlpha=.4;
if(active){const flame=rand(18,30);const g=ctx.createLinearGradient(0,11,0,flame+11);g.addColorStop(0,'#73f5df');g.addColorStop(1,'#73f5df00');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-6,10);ctx.lineTo(0,flame+10);ctx.lineTo(6,10);ctx.closePath();ctx.fill()}
ctx.shadowColor='#73f5df';ctx.shadowBlur=22;ctx.fillStyle='#e7fffb';ctx.beginPath();ctx.moveTo(0,-18);ctx.lineTo(11,11);ctx.lineTo(0,7);ctx.lineTo(-11,11);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#183b44';ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(4,4);ctx.lineTo(0,2);ctx.lineTo(-4,4);ctx.closePath();ctx.fill();if(ship.invuln>0){ctx.strokeStyle=`rgba(115,245,223,${.35+Math.sin(time*16)*.2})`;ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,21,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function draw(){ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#08121c');sky.addColorStop(.58,'#0b1c28');sky.addColorStop(1,'#102936');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
const glow=ctx.createRadialGradient(w*.5,h*.76,0,w*.5,h*.76,h*.63);glow.addColorStop(0,'rgba(40,111,118,.2)');glow.addColorStop(1,'rgba(7,16,25,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
for(const s of stars){ctx.globalAlpha=.25+s.z*.58;ctx.fillStyle=s.z>.8?'#d8fbf2':'#91acb8';ctx.fillRect(s.x,s.y,s.r*s.z,s.r*s.z)}ctx.globalAlpha=1;
// distant route guides
ctx.save();ctx.strokeStyle='rgba(115,245,223,.055)';ctx.lineWidth=1;ctx.setLineDash([3,14]);for(let x=w*.16;x<w;x+=w*.17){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}ctx.setLineDash([]);ctx.restore();
const ox=shake?rand(-shake,shake):0,oy=shake?rand(-shake,shake):0;ctx.save();ctx.translate(ox,oy);
for(const o of rocks){ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.rot);const grad=ctx.createLinearGradient(-o.r,-o.r,o.r,o.r);grad.addColorStop(0,o.shade>.5?'#59636a':'#414f59');grad.addColorStop(1,'#202d38');ctx.fillStyle=grad;ctx.strokeStyle='#a7c0c037';ctx.lineWidth=1.2;ctx.beginPath();o.pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffffff0b';ctx.beginPath();ctx.arc(-o.r*.2,-o.r*.22,o.r*.28,0,Math.PI*2);ctx.fill();ctx.restore()}
for(const p of pickups){const pulse=1+Math.sin(p.phase)*.18;ctx.save();ctx.translate(p.x,p.y);ctx.scale(pulse,pulse);ctx.shadowColor='#73f5df';ctx.shadowBlur=18;ctx.rotate(Math.PI/4);ctx.fillStyle='#73f5df';ctx.fillRect(-6,-6,12,12);ctx.shadowBlur=0;ctx.strokeStyle='#d9fff6';ctx.lineWidth=1;ctx.strokeRect(-4,-4,8,8);ctx.restore()}
for(const p of sparks){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;if(mode==='playing'||mode==='paused')shipDraw();ctx.restore();
// boost streaks
if(mode==='playing'&&boosting&&boostFuel>0){ctx.strokeStyle='#73f5df1a';ctx.lineWidth=2;for(let i=0;i<9;i++){let x=(i*97+time*73)%w;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h*.22);ctx.stroke()}}
}
function frame(now){if(mode!=='playing')return;const dt=Math.min(.034,(now-last)/1000||0);last=now;update(dt);draw();if(mode==='playing')requestAnimationFrame(frame)}
function idleFrame(now){if(mode==='playing')return;const dt=Math.min(.04,(now-last)/1000||0);last=now;time+=dt;for(const s of stars){s.y+=dt*13*s.z;if(s.y>h){s.y=0;s.x=Math.random()*w}}draw();requestAnimationFrame(idleFrame)}
last=performance.now();requestAnimationFrame(idleFrame);
})();
</script>
</body>
</html>

